export default {
	data() {
		return {
			// onPullDownRefresh: function () {
			//   wx.stopPullDownRefresh()
			// },
			userName:"",
			userCode:"",
			clicked:false,
			infoText:"sss"
		};
	},

	components: {},
	props: {},
	onLoad: function() {
		console.log(this.$data.userName);
		
	},
		
	methods:{
		onClickSignin: function() {
			console.log(this.userCode.match(/[\uff00-\uffff]/g));
			var that=this;
			if(!this.$data.userName || !this.$data.userName){
				uni.showToast({
					title:'请输入用户名或密码',
					icon:'none',
					position:'bottom'
				})
				return false
			}
			if (!this.$data.clicked){
				this.setData({
					clicked:true
				})
				uni.request({
					url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/checkusercred',
					method: 'POST',
					data: {
						userName: this.$data.userName,
						userCode: this.$data.userCode,
					},
					success: function(res) {
						that.setData({
							infoText:that.userCode+"  "+that.userName
						})
						console.log(res);
						if (res.data.localeCompare("Nope!")==0){
							//wrong unm/pcd
							uni.showToast({
								title:'用户名密码错误',
								icon:'none',
								position:'bottom'
							})
							that.setData({
								clicked:false
							})
						}else{
							getApp().globalData.openId=res.data;
							//get user vat and nm
							uni.request({
								url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getuser',
								method: 'POST',
								data: {
									openId: getApp().globalData.openId
								},success:function(res){
									console.log(res);
									getApp().globalData.userNameGG=res.data.Items[0].nickName;
									getApp().globalData.userAvatarUrlGG=res.data.Items[0].avtUrl;
									console.log("glb dta "+getApp().globalData.openId);
									uni.showToast({
										title:'登陆成功',
										icon:'none',
										position:'bottom'
									})
									that.setData({
										clicked:false
									})
									uni.switchTab({
										url: '../userInfo/userInfo',
									});
									uni.setStorage({
										key:"unmGG",
										data: getApp().globalData.userNameGG
									})
									uni.setStorage({
										key:"avtGG",
										data: getApp().globalData.userAvatarUrlGG
									})
									uni.setStorage({
										key:"oidGG",
										data: getApp().globalData.openId
									})
								}
							})
							
						}
					}
				})
			}
		},
		setData: function(obj, callback) {
			let that = this;
			let keys = [];
			let val, data;
			Object.keys(obj).forEach(function(key) {
				keys = key.split('.');
				val = obj[key];
				data = that.$data;
				keys.forEach(function(key2, index) {
					if (index + 1 == keys.length) {
						that.$set(data, key2, val);
					} else {
						if (!data[key2]) {
							that.$set(data, key2, {});
						}
					}
		
					data = data[key2];
				});
			});
			callback && callback();
		}
	}
	
}
